# ------------------------------------------------------------------ fixtures
def _expected() -> dict:
    if "expected" not in _CACHE:
        _CACHE["expected"] = json.loads(zlib.decompress(base64.b64decode(_EXPECTED_BLOB)).decode("utf-8"))
    return _CACHE["expected"]


def _scratch(tag: str) -> Path:
    root = Path(tempfile.mkdtemp(prefix=f"pc-{tag}-"))
    root.chmod(0o777)
    return root


def _private(tag: str) -> Path:
    root = Path(tempfile.mkdtemp(prefix=f"pc-{tag}-"))
    root.chmod(0o700)
    return root


def _unpack(blobs: dict[str, str], where: Path) -> Path:
    where.mkdir(parents=True, exist_ok=True)
    for name, blob in blobs.items():
        target = where / name
        target.write_bytes(zlib.decompress(base64.b64decode(blob)))
        target.chmod(0o644)
    for p in [where, *where.parents]:
        if str(p) == "/":
            break
        p.chmod(p.stat().st_mode | 0o555)
    return where


def _text_dir(files: dict[str, str], where: Path) -> Path:
    where.mkdir(parents=True, exist_ok=True)
    for name, text in files.items():
        (where / name).write_bytes(text.encode("utf-8"))
        (where / name).chmod(0o600)
    where.chmod(0o700)
    return where


def _fixture(key: str) -> Path:
    # Source corpora are program input and readable by it; expected tables stay root-only and
    # reach the program only through _copy_upstream, after every run they could answer is done.
    if key not in _CACHE:
        if key == "eval_corpus":
            _CACHE[key] = _unpack(_EVAL_DATA, _scratch("fleet") / "sources")
        elif key == "shipped_corpus":
            _CACHE[key] = _unpack(_SHIPPED_DATA, _scratch("shipped") / "sources")
        else:
            _CACHE[key] = _text_dir(_expected()[key], _private(key) / "stage")
    return _CACHE[key]


def _copy_upstream(source: Path, tag: str) -> Path:
    dest = _scratch(tag) / "upstream"
    dest.mkdir()
    for p in sorted(source.iterdir()):
        if p.is_file():
            shutil.copyfile(p, dest / p.name)
            (dest / p.name).chmod(0o666)
    dest.chmod(0o777)
    return dest


# ------------------------------------------------------------------ running the delivered program
def _grant_read(argument: str) -> None:
    """Agent editors can leave files at 0600; the verifier is root and widens them."""
    if not argument.startswith("/app"):
        return
    path = Path(argument)
    if not path.exists():
        return
    try:
        path.chmod(path.stat().st_mode | (0o555 if path.is_dir() else 0o444))
        for parent in path.parents:
            parent.chmod(parent.stat().st_mode | 0o555)
            if str(parent) == "/app":
                break
    except OSError:
        pass


def _privileged() -> bool:
    return os.name == "posix" and os.geteuid() == 0


def _untrusted_command(command: list[str]) -> list[str]:
    if _privileged():
        for argument in command:
            _grant_read(argument)
        return [*_SETPRIV, *command]
    return command


def _sweep_unprivileged() -> None:
    # A child that calls setsid escapes killpg; kill every process of the unprivileged user so
    # nothing the program started survives into a later run.
    if not _privileged():
        return
    try:
        uid = pwd.getpwnam("nobody").pw_uid
    except KeyError:
        return
    for _ in range(5):
        found = False
        for entry in Path("/proc").iterdir():
            if not entry.name.isdigit():
                continue
            try:
                if entry.stat().st_uid == uid:
                    os.kill(int(entry.name), signal.SIGKILL)
                    found = True
            except OSError:
                continue
        if not found:
            return
        time.sleep(0.05)


def _remaining() -> float:
    if not _DEADLINE:
        _DEADLINE.append(time.monotonic() + _RUN_BUDGET_SEC)
    return _DEADLINE[0] - time.monotonic()


def _run(args: list[str], timeout: int) -> tuple[int, str, str] | None:
    if not PROGRAM.is_file():
        return None
    limit = min(float(timeout), _remaining())
    if limit < 5:
        return None
    work = _scratch("cwd")
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8", "HOME": str(work)}
    try:
        proc = subprocess.Popen(_untrusted_command([sys.executable, "-I", str(PROGRAM), *args]), cwd=str(work),
                                env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
                                start_new_session=True)
    except OSError:
        return None
    try:
        out, err = proc.communicate(timeout=limit)
        code = proc.returncode
    except subprocess.TimeoutExpired:
        out, err, code = "", "", None
    finally:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except OSError:
            pass
        if proc.poll() is None:
            proc.wait()
        _sweep_unprivileged()
    return None if code is None else (code, out, err)


def _snapshot(directory: Path) -> dict[str, str] | None:
    if not directory.is_dir():
        return None
    return {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(directory.iterdir()) if p.is_file()}


def _collect(ran: tuple[int, str, str] | None, dest: Path, phase: str) -> dict | None:
    if ran is None or ran[0] != 0:
        return None
    files = {}
    for name in STAGE_FILES[phase]:
        p = dest / name
        files[name] = p.read_bytes() if p.is_file() else None
    return {"files": files, "dest": dest}


UPSTREAM = {"p2_eval": ("eval_p1",), "p2_alt": ("alt_p1",), "p2_planted": ("eval_p1",), "p2_own": None,
            "p3_eval": ("eval_p1", "eval_p2"), "p3_alt": ("alt_p1", "alt_p2"),
            "p3_planted": ("eval_p1", "eval_p2"), "p3_own": None}


def _compute(kind: str) -> dict | None:
    if kind in ("p1_eval", "p1_renamed", "p1_planted"):
        corpus = _fixture("eval_corpus")
        if kind == "p1_renamed":
            moved = _scratch("moved") / "copy_of_inputs_b"
            shutil.copytree(corpus, moved)
            for p in [moved, *moved.iterdir()]:
                p.chmod(0o755 if p.is_dir() else 0o644)
            corpus = moved
        dest = _scratch(kind) / "phase_one"
        return _collect(_run(["phase1", str(corpus), str(dest)], 900), dest, "p1")
    if kind == "p1_shipped":
        dest = _scratch(kind) / "phase_one"
        return _collect(_run(["phase1", str(_fixture("shipped_corpus")), str(dest)], 1500), dest, "p1")
    if kind in ("p1_repeat", "p2_repeat", "p3_repeat"):
        phase = kind[:2]
        first = _stage(f"{phase}_eval")
        if first is None:
            return None
        if phase == "p1":
            args = ["phase1", str(_fixture("eval_corpus"))]
        elif phase == "p2":
            args = ["phase2", str(first["upstream"][0])]
        else:
            args = ["phase3", str(first["upstream"][0][0]), str(first["upstream"][0][1])]
        return _collect(_run([*args, str(first["dest"])], 900 if phase == "p1" else 600), first["dest"], phase)
    if kind.startswith("p2_"):
        up = UPSTREAM[kind]
        upstream = _copy_upstream(_fixture(up[0]) if up else OUT / "p1", kind)
        before = _snapshot(upstream)
        dest = _scratch(kind) / "phase_two"
        result = _collect(_run(["phase2", str(upstream), str(dest)], 600), dest, "p2")
        if result is not None:
            result["upstream"] = (upstream, before, _snapshot(upstream))
        return result
    if kind.startswith("p3_"):
        pair = UPSTREAM[kind]
        one = _copy_upstream(_fixture(pair[0]) if pair else OUT / "p1", kind + "a")
        two = _copy_upstream(_fixture(pair[1]) if pair else OUT / "p2", kind + "b")
        before = (_snapshot(one), _snapshot(two))
        dest = _scratch(kind) / "phase_three"
        result = _collect(_run(["phase3", str(one), str(two), str(dest)], 600), dest, "p3")
        if result is not None:
            result["upstream"] = ((one, two), before, (_snapshot(one), _snapshot(two)))
        return result
    raise ValueError(kind)


def _stage(kind: str) -> dict | None:
    if kind not in _CACHE:
        try:
            _CACHE[kind] = _compute(kind)
        except Exception:
            _CACHE[kind] = None
    return _CACHE[kind]


def _planted(kinds: list[str]) -> dict[str, dict | None]:
    """Run the given stages with the shipped sources sitting at their usual path."""
    if PLANT.exists():
        return {k: None for k in kinds}
    try:
        _unpack(_SHIPPED_DATA, PLANT)
        return {k: _stage(k) for k in kinds}
    finally:
        shutil.rmtree(PLANT, ignore_errors=True)


# ------------------------------------------------------------------ command-line contract runs
def _one_error_line(err: str) -> bool:
    lines = [ln for ln in err.splitlines() if ln.strip()]
    return len(lines) == 1 and lines[0].startswith("build.py: error: ")


def _cli_bad_arguments() -> bool:
    runs = [_run(["phase9", "/tmp", "/tmp"], 60), _run([], 60), _run(["phase2", "/tmp"], 60)]
    return all(r is not None and r[0] == 2 and _one_error_line(r[2]) for r in runs)


def _cli_nested_output() -> bool:
    dest = _scratch("nest") / "a" / "b" / "c"
    ran = _run(["phase2", str(_copy_upstream(_fixture("eval_p1"), "nest_up")), str(dest)], 600)
    return ran is not None and ran[0] == 0 and all((dest / n).is_file() for n in STAGE_FILES["p2"])


def _cli_missing_upstream() -> bool:
    root = _scratch("gone")
    dest = root / "out"
    ran = _run(["phase2", str(root / "no_such_phase_one"), str(dest)], 120)
    wrote = dest.exists() and any(dest.iterdir())
    return ran is not None and ran[0] == 3 and _one_error_line(ran[2]) and not wrote


def _cli_missing_upstream_file() -> bool:
    two = _copy_upstream(_fixture("eval_p2"), "holey")
    (two / "tenant_pool.csv").unlink()
    dest = _scratch("holey_out") / "out"
    ran = _run(["phase3", str(_copy_upstream(_fixture("eval_p1"), "holey1")), str(two), str(dest)], 300)
    wrote = dest.exists() and any(dest.iterdir())
    return ran is not None and ran[0] == 3 and _one_error_line(ran[2]) and not wrote


def _record(key: str, fn) -> None:
    try:
        _CACHE[key] = fn()
    except Exception as exc:
        _CACHE[key] = None
        _CACHE.setdefault("errors", []).append(f"{key}: {exc!r}")


# Order matters: an expected table is copied where the program can read it only after every run
# that table grades has finished, and /app/data is planted while no other run is in flight.
_STEPS = [
    ("p1_eval", lambda: _stage("p1_eval")),
    ("p1_repeat", lambda: _stage("p1_repeat")),
    ("p1_renamed", lambda: _stage("p1_renamed")),
    ("planted_p1", lambda: _planted(["p1_planted"])),
    ("p1_shipped", lambda: _stage("p1_shipped")),
    ("cli_bad", _cli_bad_arguments),
    ("cli_gone", _cli_missing_upstream),
    ("p2_eval", lambda: _stage("p2_eval")),
    ("p2_repeat", lambda: _stage("p2_repeat")),
    ("p2_alt", lambda: _stage("p2_alt")),
    ("p2_own", lambda: _stage("p2_own")),
    ("planted_p2", lambda: _planted(["p2_planted"])),
    ("cli_nested", _cli_nested_output),
    ("p3_eval", lambda: _stage("p3_eval")),
    ("p3_repeat", lambda: _stage("p3_repeat")),
    ("p3_alt", lambda: _stage("p3_alt")),
    ("p3_own", lambda: _stage("p3_own")),
    ("planted_p3", lambda: _planted(["p3_planted"])),
    ("cli_holey", _cli_missing_upstream_file),
]


def _prepare() -> None:
    with _LOCK:
        if _CACHE.get("prepared"):
            return
        try:
            for key, fn in _STEPS:
                _record(key, fn)
        finally:
            _CACHE["prepared"] = True


def _ran(kind: str) -> dict | None:
    _prepare()
    return _CACHE.get(kind)


def _planted_run(kind: str) -> dict | None:
    _prepare()
    group = _CACHE.get(f"planted_{kind[:2]}")
    return group.get(kind) if isinstance(group, dict) else None


# ------------------------------------------------------------------ parsing helpers
def _table(data: bytes | str | None) -> list[dict[str, str]]:
    text = data.decode("utf-8") if isinstance(data, bytes) else data
    return list(csv.DictReader(io.StringIO(text, newline="")))


def _keyed(rows: list[dict[str, str]], key: str) -> dict[str, dict[str, str]]:
    return {r[key]: r for r in rows}


def _canon(value: Any) -> Any:
    """Type-strict comparison form: 32 and 32.0, or 1 and true, stay different."""
    if isinstance(value, bytes):
        return value
    return json.dumps(value, sort_keys=True)


def _covers(got: dict, want: dict, exact: bool) -> list:
    """Keys to compare. An identity check needs the exact key set; a field check compares the
    shared keys once nearly all expected keys are present, so one wrong membership decision is
    priced by the identity check alone."""
    if not want:
        return []
    if exact:
        return list(want) if got.keys() == want.keys() else []
    shared = [k for k in want if k in got]
    return shared if len(shared) >= COVERAGE * len(want) else []


def _fields_match(got: bytes | None, want: str, key: str, fields: list[str], exact: bool = False) -> bool:
    g = _keyed(_table(got), key)
    w = _keyed(_table(want), key)
    keys = _covers(g, w, exact)
    return bool(keys) and all(g[k][f] == w[k][f] for k in keys for f in fields)


def _doc(data: bytes | str | None) -> Any:
    return json.loads(data.decode("utf-8") if isinstance(data, bytes) else data)


def _delivered(phase: str, name: str) -> bytes:
    return (OUT / phase / name).read_bytes()


def _ini_sections(data: bytes | str) -> dict[str, dict[str, str]]:
    cp = configparser.ConfigParser(interpolation=None)
    cp.read_string(data.decode("utf-8") if isinstance(data, bytes) else data)
    return {s: dict(cp.items(s)) for s in cp.sections()}


def _strip_lineage(files: dict[str, bytes | None]) -> dict[str, Any]:
    view = {}
    for name, data in files.items():
        if data is None:
            view[name] = None
        elif name.endswith(".json"):
            obj = _doc(data)
            obj.pop("lineage", None)
            obj.pop("inputs", None)
            view[name] = obj
        elif name.endswith(".ini"):
            secs = _ini_sections(data)
            secs.pop("lineage", None)
            view[name] = secs
        else:
            view[name] = data
    return view


def _holds(check) -> bool:
    try:
        _prepare()
        return bool(check())
    except Exception:
        return False


def _lf_text(data: bytes) -> bool:
    return b"\r" not in data and data.endswith(b"\n")


def _exact_csv(data: bytes, header: list[str]) -> bool:
    text = data.decode("utf-8")
    return "\r" not in text and text.endswith("\n") and text.split("\n", 1)[0] == ",".join(header)


