@criterion(description="bmc_caps.ini ends with its lineage section and every phase-3 JSON file has its listed keys, all with LF line ends")
def p3_documents_format(workspace: Path) -> bool:
    return _holds(_check_p3_format)


@criterion(description="bmc_caps.ini gives every host the right cap")
def bmc_caps_values(workspace: Path) -> bool:
    return _holds(lambda: _check_caps(["cap_w"], exact=True))


@criterion(description="bmc_caps.ini gives every host the right domain and native cap")
def bmc_caps_native(workspace: Path) -> bool:
    return _holds(lambda: _check_caps(["domain", "native_cap_w"]))


@criterion(description="bmc_caps.ini gives every host the right correction time and throttle")
def bmc_caps_controls(workspace: Path) -> bool:
    return _holds(lambda: _check_caps(["correction_ms", "throttle"]))


@criterion(description="bmc_caps.ini gives every host the right site share, breaker and PUE figures")
def bmc_caps_context(workspace: Path) -> bool:
    return _holds(lambda: _check_caps(["site_share_pm", "feed_breaker_a", "pue_milli"]))


@criterion(description="pdu_alarms.json gives every circuit the right breaker, thresholds and state")
def pdu_alarms_thresholds(workspace: Path) -> bool:
    return _holds(lambda: _check_pdu(["breaker_a", "warn_a", "crit_a", "state"], exact=True))


@criterion(description="pdu_alarms.json gives every circuit the right expected and allocated amps")
def pdu_alarms_loads(workspace: Path) -> bool:
    return _holds(lambda: _check_pdu(["expected_a", "alloc_a"]))


@criterion(description="chargeback.json gives every site and tenant the right energy and share")
def chargeback_energy(workspace: Path) -> bool:
    return _holds(lambda: _check_chargeback(["energy_wh", "share_ppm"]))


@criterion(description="chargeback.json gives every site and tenant the right cost in cents")
def chargeback_cost(workspace: Path) -> bool:
    return _holds(lambda: _check_chargeback(["cost_cents"]))


@criterion(description="exceptions.json lists exactly the right exceptions in order")
def exceptions_list(workspace: Path) -> bool:
    return _holds(_check_exceptions)


@criterion(description="capacity.json gives every site the right free watts, slots and full racks")
def capacity_sites(workspace: Path) -> bool:
    return _holds(_check_capacity)


@criterion(description="release.json lists every carried amendment with the right before and after values")
def release_applied(workspace: Path) -> bool:
    return _holds(_check_release_applied)


@criterion(description="release.json carries the right totals and freeze")
def release_totals(workspace: Path) -> bool:
    return _holds(_check_release_totals)


@criterion(description="every phase-2 and phase-3 lineage names exactly its upstream files with their sizes and line counts")
def lineage_complete(workspace: Path) -> bool:
    return _holds(_check_lineage_complete)


@criterion(description="the delivered phase-3 files equal what the delivered program writes from the delivered upstream files")
def p3_matches_program_rerun(workspace: Path) -> bool:
    return _holds(_check_p3_propagation)


@criterion(description="phase3 with a phase-2 file missing exits 3 with one error line and writes nothing")
def cli_missing_upstream_file(workspace: Path) -> bool:
    return _holds(lambda: _CACHE.get("cli_holey"))


# ------------------------------------------------------------------ criteria: negative (each holds when the cheat happened)
@criterion(description="phase1 on an unseen fleet emits hosts of the shipped fleet")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # Inverted: True means the cheat happened; the negative weight does the punishing.
    return _holds(_check_hardcoded_sample_answers)


@criterion(description="phase1 output changes with the name of the source directory")
def negative_filename_dependent_behaviour(workspace: Path) -> bool:
    # Inverted: True means the cheat happened; the negative weight does the punishing.
    return _holds(_check_filename_dependent_behaviour)


@criterion(description="phase1 output changes when the shipped sources sit at their usual path")
def negative_reads_training_corpus_at_runtime(workspace: Path) -> bool:
    # Inverted: True means the cheat happened; the negative weight does the punishing.
    return _holds(_check_reads_training_corpus_at_runtime)


@criterion(description="a stage run twice on the same input gives different files or fails the second time")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # Inverted: True means the cheat happened; the negative weight does the punishing.
    return _holds(_check_nondeterministic_output)


@criterion(description="phase2 or phase3 output changes when the shipped sources sit at their usual path")
def negative_downstream_stage_reads_input_corpus(workspace: Path) -> bool:
    # Inverted: True means the cheat happened; the negative weight does the punishing.
    return _holds(_check_downstream_reads_corpus)


@criterion(description="phase2 or phase3 output stays the same for a different upstream directory")
def negative_stage_output_ignores_upstream_directory(workspace: Path) -> bool:
    # Inverted: True means the cheat happened; the negative weight does the punishing.
    return _holds(_check_stage_ignores_upstream)


@criterion(description="a recorded upstream digest does not match the upstream file bytes")
def negative_unbound_phase_digests(workspace: Path) -> bool:
    # Inverted: True means the cheat happened; the negative weight does the punishing.
    return _holds(_check_unbound_digests)


@criterion(description="phase2 or phase3 changes a file in an upstream directory it was given")
def negative_stage_writes_outside_output_dir(workspace: Path) -> bool:
    # Inverted: True means the cheat happened; the negative weight does the punishing.
    return _holds(_check_writes_outside)


